252	
253	function createStore(): Store {
254	  const workspaces: Workspace[] = [
255	    { id: "ws_studio_nova", slug: "studio-nova", name: "Studio Nova", plan: "growth", timezone: "Europe/Kyiv" },
256	    { id: "ws_brightline", slug: "brightline", name: "Brightline Fitness", plan: "starter", timezone: "Europe/Warsaw" },
257	  ];
258	  const users: User[] = [
259	    { id: "u_olena", name: "Olena Marchenko", email: "olena@studio-nova.example.test", role: "owner", workspaceSlug: "studio-nova" },
260	    { id: "u_taras", name: "Taras Hnatiuk", email: "taras@studio-nova.example.test", role: "manager", workspaceSlug: "studio-nova" },
261	    { id: "u_marta", name: "Marta Novak", email: "marta@brightline.example.test", role: "manager", workspaceSlug: "brightline" },
262	  ];
263	  const leads = seedLeads(200, workspaces, users);
264	  return { workspaces, users, leads, audit: [], nextLeadNumber: leads.length + 1 };
265	}
266	
267	// One store per server process (also survives module reloads in `next dev`).
268	const globalForStore = globalThis as unknown as { leadDeskStore?: Store };
269	const store = (globalForStore.leadDeskStore ??= createStore());
270	
271	const SESSION_PREFIX = "demo-";
272	
273	export const db = {
274	  listUsers() {
275	    return query("listUsers", () => store.users.map((user) => ({ ...user })));
276	  },
277	
278	  createSession(userId: string) {
279	    return query("createSession", () =>
280	      store.users.some((user) => user.id === userId) ? `${SESSION_PREFIX}${userId}` : null,
281	    );
282	  },
283	
284	  getUserBySession(sessionId: string) {
285	    return query("getUserBySession", () => {
286	      const userId = sessionId.startsWith(SESSION_PREFIX) ? sessionId.slice(SESSION_PREFIX.length) : "";
287	      const user = store.users.find((u) => u.id === userId);
288	      return user ? { ...user } : null;
289	    });
290	  },
291	
292	  getWorkspace(slug: string) {
293	    return query("getWorkspace", () => {
294	      const workspace = store.workspaces.find((w) => w.slug === slug);
295	      return workspace ? { ...workspace } : null;
296	    });
297	  },
298	
299	  getLeads(workspaceId: string) {
300	    return query("getLeads", () =>
301	      store.leads
302	        .filter((lead) => lead.workspaceId === workspaceId)
303	        .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
304	        .map((lead) => structuredClone(lead)),
305	    );
306	  },
307	
308	  getLead(id: string) {
309	    return query("getLead", () => {
310	      const lead = store.leads.find((l) => l.id === id);
311	      return lead ? structuredClone(lead) : null;
312	    });
313	  },
314	
315	  getLeadStats(workspaceId: string) {
316	    return query("getLeadStats", (): LeadStats => {
317	      const leads = store.leads.filter((lead) => lead.workspaceId === workspaceId);
318	      const byStatus = Object.fromEntries(LEAD_STATUSES.map((s) => [s, 0])) as Record<LeadStatus, number>;
319	      for (const lead of leads) byStatus[lead.status]++;
320	      const weekAgo = SEED_NOW - 7 * DAY_MS;
321	      const budgets = leads.map((lead) => lead.budget).filter((b): b is number => b !== null);
322	      const closed = byStatus.won + byStatus.lost;
323	      return {
324	        total: leads.length,
325	        byStatus,
326	        last7Days: leads.filter((lead) => Date.parse(lead.createdAt) >= weekAgo).length,
327	        conversionRate: closed === 0 ? 0 : byStatus.won / closed,
328	        averageBudget: budgets.length === 0 ? 0 : Math.round(budgets.reduce((a, b) => a + b, 0) / budgets.length),
329	      };
330	    });
331	  },
332	
333	  getSourceBreakdown(workspaceId: string) {
334	    return query("getSourceBreakdown", (): SourceCount[] =>
335	      LEAD_SOURCES.map((source) => ({
336	        source,
337	        count: store.leads.filter((lead) => lead.workspaceId === workspaceId && lead.source === source).length,
338	      })),
339	    );
340	  },
341	
342	  insertLead(input: NewLead) {
343	    return query("insertLead", (): Lead => {
344	      const now = new Date().toISOString();
345	      const lead: Lead = {
346	        ...input,
347	        id: leadId(store.nextLeadNumber++),
348	        fullName: `${input.firstName} ${input.lastName}`,
349	        status: "new",
350	        score: 0,
351	        assignedTo: null,
352	        tags: [],
353	        internalNotes: "",
354	        createdAt: now,
355	        updatedAt: now,
356	      };
357	      store.leads.push(lead);
358	      return structuredClone(lead);
359	    });
360	  },
361	
362	  updateLeadStatus(id: string, status: LeadStatus) {
363	    return query("updateLeadStatus", () => {
364	      const lead = store.leads.find((l) => l.id === id);
365	      if (!lead) return false;
366	      lead.status = status;
