function slugify(value: string) {
  return value
    .toLowerCase()
    .replace(/&/g, "and")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

function leadId(n: number) {
  return `lead_${String(n).padStart(4, "0")}`;
