        fullName: `${input.firstName} ${input.lastName}`,
        status: "new",
        score: 0,
        assignedTo: null,
        tags: [],
        internalNotes: "",
        createdAt: now,
        updatedAt: now,
      };
      store.leads.push(lead);
      return structuredClone(lead);
    });
  },

