    return query("deleteLead", () => {
      const index = store.leads.findIndex((l) => l.id === id);
      if (index === -1) return false;
      store.leads.splice(index, 1);
      return true;
    });
  },

  insertAuditEntry(entry: AuditEntry) {
    return query("insertAuditEntry", () => {
      store.audit.push(entry);
    });
  },
};

