import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { QuoteStatusRefresher } from "@/components/quote-status-refresher";
import { db } from "@/lib/db";
import { isQuoteStale } from "@/lib/quotes";

// The link itself is the access key: keep it out of search engines.
export const metadata: Metadata = { robots: { index: false, follow: false } };

const dateTimeFormat = new Intl.DateTimeFormat("uk-UA", { dateStyle: "medium", timeStyle: "short" });
const usd = new Intl.NumberFormat("uk-UA", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

export default async function QuotePage({ params }: PageProps<"/quotes/[id]">) {
  const { id } = await params;
  const quote = await db.getQuote(id);
  if (!quote) notFound();

  const stale = isQuoteStale(quote);

  const details: Array<[string, string]> = [
    ["Компанія", quote.company],
    ["Бюджет", quote.budget === null ? "—" : `${usd.format(quote.budget)} / міс.`],
    ["Надіслано", dateTimeFormat.format(new Date(quote.createdAt))],
  ];

  return (
    <main className="mx-auto w-full max-w-3xl flex-1 space-y-6 px-6 py-12">
      <h1 className="text-3xl font-semibold tracking-tight">Ваш кошторис</h1>

      {quote.status === "pending" && !stale && (
        <section className="flex items-center gap-3 rounded-lg border border-sky-200 bg-sky-50 p-5 text-sm">
          <span className="h-4 w-4 shrink-0 animate-spin rounded-full border-2 border-sky-300 border-t-sky-700" />
          <div>
            <p className="font-medium text-sky-900">Готуємо кошторис…</p>
            <p className="text-sky-800">Зазвичай це займає 1–2 хвилини. Сторінка оновиться сама.</p>
          </div>
          <QuoteStatusRefresher />
        </section>
      )}

      {stale && (
        <section className="space-y-1 rounded-lg border border-amber-200 bg-amber-50 p-5 text-sm">
          <p className="font-medium text-amber-900">Кошторис готується довше, ніж зазвичай</p>
          <p className="text-amber-800">
            Оновіть сторінку трохи пізніше. Якщо кошторис так і не з&apos;явиться, менеджер зв&apos;яжеться з
            вами за email, який ви вказали.
          </p>
        </section>
      )}

      {quote.status === "ready" && quote.pdfUrl && (
        <section className="space-y-3 rounded-lg border border-emerald-200 bg-emerald-50 p-5 text-sm">
          <p className="font-medium text-emerald-900">Кошторис готовий</p>
          <a
            href={quote.pdfUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex rounded-md bg-emerald-600 px-4 py-2 font-medium text-white hover:bg-emerald-700"
          >
            Завантажити PDF
          </a>
        </section>
      )}

      {quote.status === "failed" && (
        <section className="space-y-2 rounded-lg border border-red-200 bg-red-50 p-5 text-sm">
          <p className="font-medium text-red-900">Не вдалося підготувати кошторис автоматично</p>
          <p className="text-red-800">
            Ваш запит збережено — менеджер підготує кошторис вручну й надішле його на email.
          </p>
          <Link href="/quotes/new" className="inline-block text-red-900 underline">
            Надіслати новий запит
          </Link>
        </section>
      )}

      <dl className="grid grid-cols-1 gap-x-6 gap-y-3 rounded-lg border border-slate-200 bg-white p-5 text-sm sm:grid-cols-3">
        {details.map(([label, value]) => (
          <div key={label}>
            <dt className="text-slate-500">{label}</dt>
            <dd className="font-medium break-words">{value}</dd>
          </div>
        ))}
      </dl>

      <section className="space-y-2 rounded-lg border border-slate-200 bg-white p-5 text-sm">
        <h2 className="font-medium">Опис задачі</h2>
        <p className="whitespace-pre-line text-slate-700">{quote.description}</p>
      </section>
    </main>
  );
}

