    headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
    body: typeof payload === "string" ? payload : JSON.stringify(payload),
  });
}

const app = spawn("npx", ["next", "start", "-p", "3100", "-H", "127.0.0.1"], {
  env: {
    ...process.env,
    N8N_QUOTE_WEBHOOK_URL: "http://127.0.0.1:5699/webhook/quote-request",
    APP_BASE_URL: APP,
  },
  stdio: ["ignore", "ignore", "pipe"],
});
app.stderr.on("data", (d) => process.stdout.write(`[app] ${d}`));

async function submit(fields) {
  const html = await (await fetch(`${APP}/quotes/new`)).text();
  const form = new FormData();
  for (const tag of html.match(/<input[^>]*type="hidden"[^>]*>/g) ?? []) {
    const name = tag.match(/name="([^"]*)"/)?.[1];
    const value = tag.match(/value="([^"]*)"/)?.[1] ?? "";
    if (name) form.append(name, value.replace(/&quot;/g, '"').replace(/&amp;/g, "&"));
  }
  for (const [k, v] of Object.entries(fields)) form.append(k, v);
  return fetch(`${APP}/quotes/new`, { method: "POST", body: form, headers: { origin: APP }, redirect: "manual" });
}

const page = async (id) => {
  const r = await fetch(`${APP}/quotes/${id}`);
  return { status: r.status, html: await r.text() };
};
const quoteIdFrom = (res) => res.headers.get("location")?.match(/\/quotes\/([0-9a-f-]{36})/)?.[1];
const description = "Потрібен лендинг з онлайн-записом і інтеграцією з CRM";

try {
  for (let i = 0; ; i++) {
    try { if ((await fetch(`${APP}/quotes/new`)).ok) break; } catch {}
    if (i > 60) throw new Error("app did not start");
    await sleep(500);
  }

  // 1. validation
  const invalid = await submit({ company: "", email: "nope", description: "short", budget: "777" });
  const invalidHtml = await invalid.text();
  check("invalid form shows errors", invalidHtml.includes("Вкажіть назву компанії") && invalidHtml.includes("Перевірте email") && invalidHtml.includes("Оберіть бюджет зі списку"), `status ${invalid.status}`);

  // 2. happy path
  const t0 = Date.now();
  const ok = await submit({ company: "Nova Dental", email: "Owner@Nova.example.test", description, budget: "1500" });
  const id = quoteIdFrom(ok);
  check("valid form redirects to /quotes/[uuid]", Boolean(id), `status ${ok.status}, ${Date.now() - t0} ms, location ${ok.headers.get("location")}`);
  const pending = await page(id);
  check("status page shows pending", pending.html.includes("Готуємо кошторис"));
  await sleep(1000);
  const job = jobs.get(id);
  check("n8n got the job with callback url + token", job?.callbackUrl === `${APP}/api/quotes/${id}/callback` && job?.callbackToken?.length > 30 && job?.email === "owner@nova.example.test" && job?.budget === 1500);
  await sleep(3500);
  const ready = await page(id);
  check("status page shows ready + PDF link", ready.html.includes("Кошторис готовий") && ready.html.includes(`https://files.example.test/${id}.pdf`));
  check("replayed callback is rejected", (await callback(job, { status: "ready", pdfUrl: "https://evil.example.test/x.pdf" })).status === 401);

  // 3. callback auth + validation on a quote n8n has not answered yet
  const manual = await submit({ company: "Manual", email: "a@b.test", description, budget: "" });
  const manualId = quoteIdFrom(manual);
  await sleep(1000);
  const manualJob = jobs.get(manualId);
  check("wrong token -> 401", (await callback(manualJob, { status: "ready", pdfUrl: "https://x.test/a.pdf" }, "wrong")).status === 401);
  check("other quote's token -> 401", (await callback(manualJob, { status: "ready", pdfUrl: "https://x.test/a.pdf" }, job.callbackToken)).status === 401);
  check("no auth header -> 401", (await fetch(manualJob.callbackUrl, { method: "POST", body: "{}" })).status === 401);
  check("unknown quote -> 401", (await callback({ ...manualJob, callbackUrl: `${APP}/api/quotes/nope/callback` }, { status: "failed" })).status === 401);
  check("javascript: pdfUrl -> 400", (await callback(manualJob, { status: "ready", pdfUrl: "javascript:alert(1)" })).status === 400);
  check("broken JSON -> 400", (await callback(manualJob, "{not json")).status === 400);
  check("still pending after bad callbacks", (await page(manualId)).html.includes("Готуємо кошторис"));
  check("failed callback -> 200", (await callback(manualJob, { status: "failed", error: "PDF render crashed" })).status === 200);
  const failedPage = await page(manualId);
  check("status page shows failure, hides n8n error", failedPage.html.includes("Не вдалося підготувати кошторис") && !failedPage.html.includes("PDF render crashed"));

  // 4. n8n trigger fails
  const fail = await submit({ company: "Fail", email: "a@b.test", description, budget: "" });
  const failId = quoteIdFrom(fail);
  await sleep(1500);
  check("trigger failure marks quote failed", (await page(failId)).html.includes("Не вдалося підготувати кошторис"));

  // 5. unknown id
  check("unknown quote page -> 404", (await page("00000000-0000-4000-8000-000000000000")).status === 404);
} catch (error) {
  failures++;
  console.error(error);
} finally {
  app.kill();
  mock.close();
  console.log(failures === 0 ? "\nALL PASSED" : `\n${failures} FAILED`);
  process.exit(failures ? 1 : 0);
}
